import {
	alpha,
	Box,
	ButtonBase,
	Collapse,
	styled,
	Typography,
	useTheme,
} from "@mui/material";
import { FormatQuote } from "@mui/icons-material";
import {Terminal} from 'lucide-react'
import { ReactNode, useState } from "react";
import { useTranslation } from "react-i18next";
import { BranchInfo } from "./components/branch-info";
import { ExplorerHeader } from "./components/explorer-header";
import { AvailabilityDot } from "components/availability-dot";
import { projects, workExperience } from "consts";
import { useNavigationStore, FolderName } from "store/navigation-store";
import { useTerminalStore } from "store/terminal-store";
import { getFileIcon } from "config/file-icon";
import {
	ArrowDown,
	ArrowRight,
	Briefcase,
	FileBraces,
	Folder,
	FolderOpen,
	Mail,
	User,
} from "lucide-react";

const SidebarRoot = styled(Box)(({ theme }) => ({
	width: "280px",
	flexShrink: 0,
	flexDirection: "column",
	display: "flex",
	borderRight: `1px solid ${
		theme.palette.mode === "dark"
			? theme.palette.grey[400]
			: theme.palette.grey[300]
	}`,
	backgroundColor: theme.palette.mode === "light" ? "white" : "#13171d",
}));

const ExplorerBody = styled(Box)(({ theme }) => ({
	flex: 1,
	overflowY: "auto",
	overflowX: "hidden",
	padding: "8px 6px 16px",
	borderBottom:
		theme.palette.mode === "dark"
			? `1px solid ${theme.palette.grey[400]}`
			: `1px solid ${theme.palette.grey[300]}`,
}));

const SidebarFooterRoot = styled(Box)(({ theme }) => ({
	flexShrink: 0,
	display: "flex",
	flexDirection: "column",
	gap: "8px",
	padding: "6px 10px",
	color: theme.palette.text.secondary,
}));

const RowBase = styled(ButtonBase)(({ theme }) => ({
	display: "flex",
	alignItems: "center",
	gap: "6px",
	width: "100%",
	minHeight: "26px",
	padding: "0 8px",
	justifyContent: "flex-start",
	borderRadius: "4px",
	textTransform: "none",
	color: theme.palette.text.secondary,
	"&:hover": {
		backgroundColor: theme.palette.action.hover,
	},
}));

type NavItemProps = {
	icon: ReactNode;
	label: string;
	onClick?: () => void;
};

function NavItem({ icon, label, onClick }: NavItemProps) {
	return (
		<RowBase sx={{ pl: "30px" }} onClick={onClick}>
			{icon}
			<Typography
				sx={{
					fontSize: "13px",
					whiteSpace: "nowrap",
					overflow: "hidden",
					textOverflow: "ellipsis",
					color: "inherit",
				}}
			>
				{label}
			</Typography>
		</RowBase>
	);
}

type FolderItemProps = {
	label: string;
	itemIcon: (index: number) => ReactNode;
	sublabels: string[];
	onOpenFolder?: () => void;
	onOpenFile?: (label: string) => void;
};

function FolderItem({
	label,
	itemIcon,
	sublabels,
	onOpenFolder,
	onOpenFile,
}: FolderItemProps) {
	const [open, setOpen] = useState(false);
	const theme = useTheme();

	return (
		<Box>
			<RowBase
				onClick={() => {
					setOpen((prev) => !prev);
					onOpenFolder?.();
				}}
			>
				{open ? (
					<ArrowDown size={16} color={theme.palette.text.secondary} />
				) : (
					<ArrowRight size={16} color={theme.palette.text.secondary} />
				)}
				{open ? (
					<FolderOpen size={16} color={theme.palette.primary.main} />
				) : (
					<Folder size={16} color={theme.palette.primary.main} />
				)}
				<Typography
					sx={{
						fontSize: "13px",
						fontWeight: 600,
						textTransform: "uppercase",
						whiteSpace: "nowrap",
						overflow: "hidden",
						textOverflow: "ellipsis",
						color: "inherit",
					}}
				>
					{label}
				</Typography>
			</RowBase>
			<Collapse in={open} unmountOnExit>
				{sublabels.map((sublabel, index) => (
					<RowBase
						key={sublabel}
						sx={{ paddingLeft: "50px" }}
						onClick={() => onOpenFile?.(sublabel)}
					>
						{itemIcon(index)}
						<Typography
							sx={{
								fontSize: "13px",
								whiteSpace: "nowrap",
								overflow: "hidden",
								textOverflow: "ellipsis",
								color: "inherit",
							}}
						>
							{sublabel}
						</Typography>
					</RowBase>
				))}
			</Collapse>
		</Box>
	);
}

export function Sidebar() {
	const theme = useTheme();
	const { t } = useTranslation();
	const openFile = useNavigationStore((s) => s.openFile);
	const setOpenFolder = useNavigationStore((s) => s.setOpenFolder);
	const terminalOpen = useTerminalStore((s) => s.isOpen);
	const toggleTerminal = useTerminalStore((s) => s.toggle);

	const handleFileClick = (label: string, folder?: FolderName) => {
		const { id, icon } = getFileIcon(label, folder, theme);
		openFile({ id, label, icon });
	};

	const handleFolderClick = (label: string) => {
		if (label === "projects" || label === "work-experience") {
			setOpenFolder(label as FolderName);
		}
	};

	return (
		<SidebarRoot>
			<ExplorerHeader />
			<BranchInfo />
			<ExplorerBody>
				<NavItem
					label={"about-me.tsx"}
					icon={<User size={16} color={theme.palette.success.main} />}
					onClick={() => handleFileClick("about-me.tsx")}
				/>
				<FolderItem
					label={t("common::projects")}
					sublabels={projects.map((project) => project.sidebarName)}
					itemIcon={(index) => (
						<FileBraces size={16} color={theme.palette.warning.main} />
					)}
					onOpenFolder={() => handleFolderClick("projects")}
					onOpenFile={(sublabel) => handleFileClick(sublabel, "projects")}
				/>
				<FolderItem
					label={t("common::workExperience")}
					sublabels={workExperience.map((entry) => entry.sidebarName)}
					itemIcon={() => <Briefcase size={16} color="#a87eeb" />}
					onOpenFolder={() => handleFolderClick("work-experience")}
					onOpenFile={(sublabel) =>
						handleFileClick(sublabel, "work-experience")
					}
				/>
				<NavItem
					label={"new-message.tsx"}
					icon={<Mail size={16} color={theme.palette.error.main} />}
					onClick={() => handleFileClick("new-message.tsx")}
				/>
			</ExplorerBody>
			<SidebarFooterRoot>
				<RowBase onClick={toggleTerminal}>
					<Terminal size="16px" />
					<Typography
						sx={{
							fontSize: "14px",
							color: terminalOpen
								? theme.palette.primary.main
								: "inherit",
						}}
					>
						{t("sidebar::openTerminal")}
					</Typography>
					<Box sx={{ flex: 1 }} />
					<Box
						sx={{
							borderRadius: "8px",
							border: `1px solid ${theme.palette.mode === "dark" ? theme.palette.grey[400] : theme.palette.grey[300]}`,
							padding: "2px",
						}}
					>
						<FormatQuote sx={{ fontSize: "14px", color: "text.secondary" }} />
					</Box>
				</RowBase>
				<RowBase sx={{ padding: 0 }}>
					<Box
						sx={{
							borderRadius: "4px",
							color: "text.primary",
							width: "100%",
							backgroundColor: alpha(theme.palette.success.main, 0.15),
							padding: "6px 12px",
							display: "flex",
							alignItems: "center",
							gap: "4px",
						}}
					>
						<AvailabilityDot />
						<Typography
							sx={{
								fontSize: "12px",
								color: "inherit",
							}}
						>
							{t("sidebar::availableForWork")}
						</Typography>
					</Box>
				</RowBase>
			</SidebarFooterRoot>
		</SidebarRoot>
	);
}
